function CONGRUENCE(J, G):
    d <- size(G)
    Gp <- d x d zero matrix
    for a in 0..d-1:
        for b in 0..d-1:
            for i in 0..d-1:
                for j in 0..d-1:
                    Gp[a][b] <- Gp[a][b] + J[a][i]*G[i][j]*J[b][j]
    return Gp   # equals (J^T G J) with this index convention

